hints.code_snippet:
class Spell {
  constructor(name, manaCost) {
    this.name = name;
    this.manaCost = manaCost;
  }

  cast() {
    return `A generic spell named "${this.name}" is cast, costing ${this.manaCost} mana.`;
  }
}

class FireballSpell extends Spell {
  constructor(manaCost, damage) {
    // Sabotage: super() is called without passing the 'name' and 'manaCost' arguments.
    // This will cause the base class's 'this.name' and 'this.manaCost' to be undefined.
    super();
    this.damage = damage;
  }

  cast() {
    // This method attempts to use this.manaCost from the base class, which will be undefined.
    return `A powerful Fireball dealing ${this.damage} damage is launched! Cost: ${this.manaCost} mana.`;
  }
}

class HealSpell extends Spell {
  constructor(manaCost, healAmount) {
    // Sabotage: super() is called without passing the 'name' and 'manaCost' arguments.
    // This will cause the base class's 'this.name' and 'this.manaCost' to be undefined.
    super();
    this.healAmount = healAmount;
  }

  cast() {
    // This method attempts to use this.manaCost from the base class, which will be undefined.
    return `A soothing Heal spell restores ${this.healAmount} health! Cost: ${this.manaCost} mana.`;
  }
}

